package retry;

import java.time.Duration;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.Callable;
import java.util.function.Predicate;

/** Runs a task, retrying retryable failures with exponential backoff. */
public final class Retrier {
    private final RetryPolicy policy;
    private final Sleeper sleeper;

    public Retrier(RetryPolicy policy, Sleeper sleeper) {
        this.policy = Objects.requireNonNull(policy, "policy");
        this.sleeper = Objects.requireNonNull(sleeper, "sleeper");
    }

    /**
     * Calls {@code task} until it succeeds.
     *
     * @throws RetryExhaustedException if all attempts failed with retryable exceptions
     * @throws InterruptedException    if interrupted while waiting (flag is restored)
     * @throws Exception               a non-retryable failure, immediately
     */
    public <T> T call(Callable<T> task, Predicate<Exception> retryable) throws Exception {
        Objects.requireNonNull(task, "task");
        Objects.requireNonNull(retryable, "retryable");
        Duration waited = Duration.ZERO;
        for (int attempt = 1; ; attempt++) {
            try {
                return task.call();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw e;
            } catch (Exception e) {
                if (!retryable.test(e)) {
                    throw e;
                }
                if (attempt >= policy.maxAttempts()) {
                    throw new RetryExhaustedException(attempt, waited, e);
                }
                Duration delay = policy.delayBefore(attempt);
                try {
                    sleeper.sleep(delay);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    throw ie;
                }
                waited = waited.plus(delay);
            }
        }
    }

    /** Like {@link #call} but returns empty instead of throwing when attempts are exhausted. */
    public <T> Optional<T> attempt(Callable<T> task, Predicate<Exception> retryable) throws Exception {
        try {
            return Optional.ofNullable(call(task, retryable));
        } catch (RetryExhaustedException e) {
            return Optional.empty();
        }
    }
}

package retry;

import java.time.Duration;

/** Abstraction over waiting so tests need not really sleep. */
@FunctionalInterface
public interface Sleeper {
    void sleep(Duration duration) throws InterruptedException;
}

package retry;

import java.time.Duration;

/** Checked exception thrown when every allowed attempt failed with a retryable error. */
public class RetryExhaustedException extends Exception {
    private static final long serialVersionUID = 1L;

    private final int attempts;
    private final Duration totalDelay;

    public RetryExhaustedException(int attempts, Duration totalDelay, Throwable lastFailure) {
        super("gave up after " + attempts + " attempts (waited " + totalDelay + ")", lastFailure);
        this.attempts = attempts;
        this.totalDelay = totalDelay;
    }

    public int attempts() {
        return attempts;
    }

    public Duration totalDelay() {
        return totalDelay;
    }
}

package retry;

import java.time.Duration;
import java.util.Objects;

/**
 * Exponential backoff configuration.
 *
 * @param maxAttempts  total number of calls allowed (first call plus retries), at least 1
 * @param initialDelay delay before the first retry
 * @param multiplier   growth factor between retries, at least 1
 * @param maxDelay     upper bound for any single delay
 */
public record RetryPolicy(int maxAttempts, Duration initialDelay, int multiplier, Duration maxDelay) {

    public RetryPolicy {
        Objects.requireNonNull(initialDelay, "initialDelay");
        Objects.requireNonNull(maxDelay, "maxDelay");
        if (maxAttempts < 1) {
            throw new IllegalArgumentException("maxAttempts must be >= 1");
        }
        if (initialDelay.isNegative()) {
            throw new IllegalArgumentException("initialDelay must not be negative");
        }
        if (multiplier < 1) {
            throw new IllegalArgumentException("multiplier must be >= 1");
        }
        if (maxDelay.compareTo(initialDelay) < 0) {
            throw new IllegalArgumentException("maxDelay must be >= initialDelay");
        }
    }

    /**
     * Delay to wait before retry number {@code attempt} (1 is the first retry).
     * Computed iteratively and capped at {@link #maxDelay()}, so it never overflows.
     */
    public Duration delayBefore(int attempt) {
        if (attempt < 1) {
            throw new IllegalArgumentException("attempt must be >= 1");
        }
        Duration delay = initialDelay;
        for (int i = 1; i < attempt; i++) {
            if (delay.compareTo(maxDelay) >= 0 || multiplier == 1) {
                break;
            }
            try {
                delay = delay.multipliedBy(multiplier);
            } catch (ArithmeticException overflow) {
                return maxDelay;
            }
        }
        return delay.compareTo(maxDelay) > 0 ? maxDelay : delay;
    }
}

